s=s[:a]+'''if(action==='auto'){const was=s.auto;s.auto=value===true;if(s.phase==='finished'){if(s.auto&&!was)s.nextRoundAt=now+30000;else if(!s.auto)s.nextRoundAt=null;}return true;}if(action==='duration'){const n=Number(value);if(!Number.isInteger(n)||n<30||n>3600)throw Error('Duration must be 30–3600 seconds.');const delta=(n-s.seconds)*1000;s.seconds=n;if(s.phase==='playing'){s.deadline=Math.max(now,s.deadline+delta);s.remaining=Math.max(0,s.deadline-now);if(s.questionDeadline)s.questionDeadline=Math.min(s.questionDeadline,s.deadline);}else if(s.phase==='reveal'){s.roundRemaining=Math.max(0,s.roundRemaining+delta);s.remaining=s.roundRemaining;s.endRoundAfterReveal=s.roundRemaining<=0;}else if(s.phase==='paused'){s.remaining=Math.max(0,s.remaining+delta);if(s.pausedPhase==='reveal'){s.roundRemaining=s.remaining;s.endRoundAfterReveal=s.remaining<=0;}else s.questionRemaining=Math.min(s.questionRemaining,s.remaining);}else if(s.phase!=='finished')s.remaining=n*1000;return true;}''' +s[b:]
